 if(kind==='ellipse'||kind==='terminal')return new fab.Ellipse({...defaults,rx:64,ry:41});
 if(kind==='triangle')return new fab.Triangle({...defaults,width:110,height:100});
 if(kind==='diamond'||kind==='decision')return new fab.Polygon(polygon(4),defaults);
 if(/^polygon/.test(kind))return new fab.Polygon(polygon(Number(kind.slice(7))),defaults);
