const replaced=new Set(['rect','ellipse','triangle']);
// Preview the actual Fabric geometry used by insert(), rather than a placeholder glyph.
// Rendering is deferred until a card enters the viewport to keep large catalogs responsive.
const previewCache=new Map();
let previewObserver=null;
function previewData(kind){
 if(previewCache.has(kind))return previewCache.get(kind);
 const obj=create(kind);
 const canvas=document.createElement('canvas');canvas.width=128;canvas.height=84;
 const ctx=canvas.getContext('2d');
 if(!ctx)throw Error('Canvas 2D context is unavailable');
 // Reposition only the temporary preview object; the inserted object is untouched.
 const width=Math.max(1,obj.width||1),height=Math.max(1,obj.height||1);
 const scale=Math.min(96/width,65/height);
 obj.set({originX:'center',originY:'center',left:64,top:42,scaleX:scale,scaleY:scale,
   fill:'rgba(163,213,255,0.15)',stroke:'#a3d5ff',strokeWidth:2,strokeUniform:true,opacity:1});
 obj.setCoords();obj.render(ctx);
 const url=canvas.toDataURL('image/png');previewCache.set(kind,url);return url;
}
function previewIcon(icon,kind){
 icon.dataset.previewKind=kind;
 icon.dataset.previewFallback=icon.textContent;
 if(previewObserver)previewObserver.observe(icon);
 else loadPreview(icon);
}
function loadPreview(icon){
 const kind=icon.dataset.previewKind;
 if(!kind||!icon.isConnected)return;
 try{
   const img=document.createElement('img');img.src=previewData(kind);img.alt='';
   img.width=64;img.height=42;img.style.cssText='display:block;width:64px;height:42px;max-width:100%;object-fit:contain';
   icon.replaceChildren(img);
 }catch(err){console.warn('Element preview unavailable:',kind,err);}
 delete icon.dataset.previewKind;
}
if(typeof IntersectionObserver!=='undefined')previewObserver=new IntersectionObserver(items=>{
 for(const item of items)if(item.isIntersecting){previewObserver.unobserve(item.target);loadPreview(item.target)}
},{rootMargin:'160px'});
const toolPreviewKinds={rect:'rect',ellipse:'ellipse',triangle:'triangle',arrow:'right'};
function render(){
 const grid=byId('vsElementGrid');
 let storage=byId('vsElementsPanel').querySelector('.vs-element-tool-storage');
 if(!storage){storage=document.createElement('div');storage.className='vs-element-tool-storage';storage.hidden=true;byId('vsElementsPanel').append(storage)}
 grid.querySelectorAll('[data-tool]').forEach(btn=>storage.append(btn));
 grid.replaceChildren();
 for(const [cat,id,label,glyph] of drawingTools){
  const btn=document.querySelector(`.vs-element-tool-storage [data-tool="${id}"]`)||grid.querySelector(`[data-tool="${id}"]`)||document.querySelector(`[data-tool="${id}"]`);
  if(!btn)continue;
  // Keep the original DOM button and its event listeners. Move it into the card.
  const storage=byId('vsElementsPanel').querySelector('.vs-element-tool-storage');
  if(storage&&btn.parentElement!==storage)storage.append(btn);
  if(category!=='all'&&category!==cat)continue;
  const card=document.createElement('div');card.className='vs-element-card vs-element-tool-card';
  const icon=document.createElement('span');icon.className='vs-element-glyph';icon.textContent=glyph;
  const name=document.createElement('span');name.textContent=label;
  btn.classList.add('vs-unified-tool');btn.textContent='';btn.title=label;btn.append(icon,name);
  card.append(btn);grid.append(card);
  if(toolPreviewKinds[id])previewIcon(icon,toolPreviewKinds[id]);
 }
 for(const entry of entries){
  if(replaced.has(entry[3]))continue; // A single visible action for these shapes.
  if(category!=='all'&&entry[0]!==category)continue;
  const b=document.createElement('button');b.type='button';b.className='vs-element-card';b.title='Вмъкни '+entry[1];
  const icon=document.createElement('span');icon.className='vs-element-glyph';icon.textContent=entry[2];
  const name=document.createElement('span');name.textContent=entry[1];b.append(icon,name);
  b.addEventListener('click',()=>insert(entry));grid.append(b);
  previewIcon(icon,entry[3]);
 }
 renderTextModes(grid);
 renderAdvancedText(grid);
 const total=byId('vsElementCount');if(total)total.textContent=grid.childElementCount+' елемента и инструмента';
 byId('vsElementCategories').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.category===category));
}

function init(){const panel=byId('vsElementsPanel');if(!panel)return;const categories=byId('vsElementCategories');Object.entries(groups).forEach(([id,name])=>{const b=document.createElement('button');b.type='button';b.dataset.category=id;b.textContent=name;b.onclick=()=>{category=id;render()};categories.append(b)});byId('vsElementsTab').addEventListener('click',showPanel);byId('vsElementsLaunch')?.addEventListener('click',()=>{const sidebar=document.querySelector('.sidebar');sidebar?.classList.remove('vs-collapsed');showPanel()});byId('vsOpenSymbols').onclick=()=>document.querySelector('.sidebar [data-tab="objects"]').click();render();showPanel();
 // All drawing buttons remain singletons. No second toolbar is built here.
 document.querySelectorAll('[data-tool]').forEach(btn=>{
   btn.setAttribute('aria-label',btn.title||btn.dataset.tool);
   btn.setAttribute('type','button');
 });
}
window.addEventListener('load',init);
window.VectorStudioElements={entries:entries.map(e=>({category:e[0],name:e[1],kind:e[3]})),create};
